{
  "version": 1,
  "source": "isolated-source",
  "commands": [
    {
      "type": "watchlists.getRows",
      "description": "Read displayed Watch rows/state or bounded formula-safe CSV text; no file/clipboard writes or freshness claim.",
      "mutates": false,
      "params": {
        "offset": "0-100000, default 0",
        "limit": "1-100, default 25",
        "format": "rows (default)|csv; CSV <=128 KiB",
        "columns": "CSV only: 1-24 visible column IDs; default visible columns"
      },
      "effects": [
        "none"
      ]
    },
    {
      "type": "watchlists.select",
      "description": "Select a discovered list OR visible row on the active chart. Mounted Watch required; poll rows/chart.",
      "mutates": true,
      "params": {
        "kind": "category|watchlist|flaglist; with name",
        "name": "Exact list ID",
        "symbol": "Visible row ticker; instead of kind/name",
        "clearFilters": "Explicit true to discard applied screeners on list switch"
      },
      "effects": [
        "navigate",
        "quota",
        "network",
        "write"
      ]
    },
    {
      "type": "watchlists.setView",
      "description": "Set mounted Watch sort/filter/column state. Existing column preferences persist; filters are session-only.",
      "mutates": true,
      "params": {
        "sort": "Up to 12 {colId,sort:asc|desc}; [] clears",
        "filters": "AG text/number/set by column ID; two-condition AND/OR; {} clears",
        "columns": "Up to 24 {colId,hide?,width?,pinned?}, in order",
        "search": "Optional quick-filter text, <=80 chars; empty clears",
        "move": "Exclusive {symbol,toIndex}: move an existing row in unfiltered, unsorted manual order"
      },
      "effects": [
        "panel",
        "write"
      ]
    },
    {
      "type": "watchlists.removeSymbols",
      "description": "Remove 1-100 symbols from an existing cloud watchlist using the UI writer.",
      "mutates": true,
      "params": {
        "name": "Existing watchlist",
        "symbols": "1-100 unique canonical tickers"
      },
      "effects": [
        "network",
        "write"
      ]
    },
    {
      "type": "watchlists.manage",
      "description": "Manage lists/favorite stars or flag visible rows using guarded UI stores. Delete requires confirm:true.",
      "mutates": true,
      "params": {
        "action": "rename|delete|favorite|flag",
        "name": "Existing list/category; not for flag",
        "newName": "Rename only",
        "confirm": "Delete only: true",
        "kind": "Favorite only: watchlist|category",
        "enabled": "Favorite only: required boolean",
        "symbols": "Flag only: 1-100 unique visible tickers",
        "color": "Flag only: red|blue|green|yellow|purple|cyan|pink|currentColor (remove)"
      },
      "effects": [
        "panel",
        "network",
        "write"
      ]
    },
    {
      "type": "symbol.details",
      "description": "Read bounded mounted company/fundamentals without a write grant; expanded changes require write approval and a retry key. No automatic fetch while collapsed.",
      "mutates": false,
      "params": {
        "expanded": "Optional boolean; poll after opening"
      },
      "effects": [
        "panel",
        "write"
      ]
    },
    {
      "type": "peers.get",
      "description": "Read up to 100 matched/unmatched peers for the mounted Peers panel's current chart symbol.",
      "mutates": false,
      "params": {
        "limit": "1-100, default 25"
      },
      "effects": [
        "none"
      ]
    },
    {
      "type": "peers.configure",
      "description": "Reload mounted peers through the UI Refresh/Retry path; poll peers.get. Does not scrape upstream.",
      "mutates": true,
      "params": {
        "refresh": "Required true; reload stored peers and chart catalog"
      },
      "effects": [
        "network",
        "write"
      ]
    },
    {
      "type": "indices.getState",
      "description": "Read index catalog/constituents without a write grant; category selection requires write approval and a retry key and opens its index on chart.",
      "mutates": false,
      "params": {
        "category": "Optional published category ID",
        "offset": "0-100000, default 0",
        "limit": "1-100, default 25"
      },
      "effects": [
        "navigate",
        "write",
        "quota",
        "network"
      ]
    },
    {
      "type": "heatmap.configure",
      "description": "Configure mounted heatmap using its offered universe/options; no historical period exists. Poll getState.",
      "mutates": true,
      "params": {
        "universe": "Exact offered universe ID",
        "sizeMode": "turnover|volume|percent|equal",
        "groupBy": "sector|none",
        "colorScale": "2|3|5|10",
        "limit": "0|50|100|250|500",
        "search": "Optional highlight query, <=80 chars",
        "expanded": "Optional boolean"
      },
      "effects": [
        "panel",
        "write"
      ]
    },
    {
      "type": "watchlists.multiView",
      "description": "Read mounted Multi Watchlists without a write grant; panels replacement requires write approval and a retry key.",
      "mutates": false,
      "params": {
        "panels": "Optional array of {type:category|watchlist|flaglist,name}; [] closes all cards"
      },
      "effects": [
        "panel",
        "write"
      ]
    },
    {
      "type": "chart.viewState",
      "description": "Read bounded native chart view/scale/timezone and drawing toolbar state.",
      "mutates": false,
      "params": {},
      "effects": [
        "none"
      ]
    },
    {
      "type": "chart.setView",
      "description": "Set native view; ranges request positioning, not verified history. Symbol/interval: chart.open. Date: guarded navigator.",
      "mutates": true,
      "params": {
        "chartType": "Optional named chart type.",
        "priceScale": "{mode?:normal|percent|log,autoScale?:boolean}",
        "visibleRange": "{preset:5y|1y|6m|3m|1m|5d|1d} OR {from,to} epoch seconds",
        "goToDate": "UTC date, offset ISO timestamp, or epoch seconds.",
        "timezone": "Available timezone ID from viewState.",
        "legend": "{ohlcVisible:boolean}"
      },
      "effects": [
        "navigate",
        "quota",
        "network",
        "write"
      ]
    },
    {
      "type": "chart.compare",
      "description": "List/add/remove native Compare/Overlay only; never other studies. Adds use selected feed; no fallback.",
      "mutates": true,
      "params": {
        "action": "list|add|remove",
        "symbol": "Required for add.",
        "kind": "Optional add: compare (default)|overlay.",
        "id": "Exact listed id for remove.",
        "offset": "Optional list offset.",
        "limit": "Optional list 1-50."
      },
      "effects": [
        "navigate",
        "quota",
        "network",
        "write"
      ]
    },
    {
      "type": "chart.action",
      "description": "Request native toolbar action. Screenshot returns bounded PNG, not a file. Replay guards undo/redo/date/compare.",
      "mutates": true,
      "params": {
        "action": "undo|redo|settings|screenshot|fullscreen|resetScale|objectTree|compareDialog|goToDate",
        "enabled": "Required boolean only for fullscreen."
      },
      "effects": [
        "panel",
        "write"
      ]
    },
    {
      "type": "drawings.list",
      "description": "Page user drawings only: id/tool, up to 10 time/price points, visible/locked; excludes managed visuals.",
      "mutates": false,
      "params": {
        "offset": "Optional 0-10000.",
        "limit": "Optional 1-50, default 50."
      },
      "effects": [
        "none"
      ]
    },
    {
      "type": "drawings.create",
      "description": "Create one allowlisted user drawing with exact tool point count. Epoch seconds/prices; no raw overrides.",
      "mutates": true,
      "params": {
        "tool": "Allowlisted tool; see public guide.",
        "points": "1-7 {time:integer epoch seconds,price:finite}",
        "text": "Optional text for text tool, max 500.",
        "locked": "Optional boolean."
      },
      "effects": [
        "write"
      ]
    },
    {
      "type": "drawings.update",
      "description": "Hide/lock/remove up to 50 exact user drawing IDs; never studies or managed visuals. Preflights all targets; not transactional.",
      "mutates": true,
      "params": {
        "ids": "1-50 unique IDs from list.",
        "visible": "Optional boolean.",
        "locked": "Optional boolean.",
        "remove": "Optional true; exclusive with visible/locked."
      },
      "effects": [
        "write"
      ]
    },
    {
      "type": "drawings.setMode",
      "description": "Set drawing modes/tool or reorder existing favorites. Confirmed removeAll deletes all user drawings, preserving managed visuals.",
      "mutates": true,
      "params": {
        "tool": "Optional allowlisted drawing/cursor/brush/measure/zoom tool.",
        "magnet": "Optional boolean.",
        "lockAll": "Optional boolean.",
        "hideAll": "Optional boolean.",
        "favoriteOrder": "All current favorite tool IDs from chart.viewState, ordered; max 50.",
        "removeAll": "Optional true.",
        "confirm": "Required true only with removeAll."
      },
      "effects": [
        "write"
      ]
    },
    {
      "type": "studyTemplates.manage",
      "description": "Native indicator templates, not drawing styles/layouts. Apply replaces native studies only, preserving symbol/interval; no replay. Indicator grant/retry key required, including list.",
      "mutates": true,
      "permission": "indicators",
      "params": {
        "action": "list|save|apply|delete",
        "name": "Required except list; max 80.",
        "replace": "save only: true to overwrite.",
        "confirm": "Required true for apply/delete.",
        "offset": "list only, 0-10000.",
        "limit": "list only, 1-50."
      },
      "effects": [
        "write"
      ]
    },
    {
      "type": "layout.getState",
      "description": "Read split-chart layout: active pane, maximized pane, split sizes and each pane's last symbol/feed/interval. chart.*/studies.*/indicators.* always target the active pane.",
      "mutates": false,
      "params": {
        "saved": "Optional boolean: also list up to 50 saved chart layouts (needs sign-in)."
      },
      "effects": [
        "none"
      ]
    },
    {
      "type": "layout.set",
      "description": "Change split layout, active pane (retargets chart.* commands), focus/restore, split sizes, fullscreen or pane linking.",
      "mutates": true,
      "params": {
        "layout": "single|columns|rows|grid",
        "activePane": "Pane id in layout",
        "maximize": "bool",
        "horizontal": "25-75",
        "vertical": "25-75",
        "fullscreen": "bool",
        "sync": "{symbol?,interval?} bools: active pane drives others"
      },
      "effects": [
        "navigate",
        "panel",
        "quota",
        "network",
        "write"
      ]
    },
    {
      "type": "layout.saved",
      "description": "Save the active pane's chart as a named saved layout, or load a saved layout id (from layout.getState saved:true) into the active pane, replacing its chart.",
      "mutates": true,
      "params": {
        "action": "save|load.",
        "name": "save: 1-64 chars.",
        "id": "load: saved layout id."
      },
      "effects": [
        "navigate",
        "panel",
        "quota",
        "network",
        "write"
      ]
    },
    {
      "type": "grid.getState",
      "description": "Read the mounted Chart Grid: settings, universe, ranking, paging and a bounded page of card symbols with load status.",
      "mutates": false,
      "params": {
        "offset": "Optional 0-499 card offset.",
        "limit": "Optional 1-100, default 24.",
        "options": "Optional boolean: include universe choices (max 200)."
      },
      "effects": [
        "none"
      ]
    },
    {
      "type": "grid.configure",
      "description": "Change the mounted Chart Grid; source/sort/filter/paging changes reset page. Verify with grid.getState.",
      "mutates": true,
      "params": {
        "universe": "getState option",
        "timeframe": "5-1M",
        "candles": "50-500",
        "density": "size",
        "pageSize": "6|12|18|24",
        "paging": "pages|more",
        "indicators": "sma20|ema50",
        "volume": "bool",
        "sort": "{field,direction}",
        "filters": "partial; null clears",
        "page": "1-based",
        "linkTimeframe": "bool",
        "refresh": "true",
        "chartIndicators": "copy|basic",
        "theme": "id",
        "width": "px",
        "expanded": "bool",
        "openCard": "page symbol to active chart",
        "panel": "close|openPage, alone"
      },
      "effects": [
        "panel",
        "write"
      ]
    },
    {
      "type": "grid.open",
      "description": "Open the Chart Grid sidebar, optionally with explicit symbols or a completed visible scan's tickers in grid order.",
      "mutates": true,
      "params": {
        "symbols": "1-500 tickers",
        "runId": "Screening runId",
        "scope": "all|filtered|selected scan rows",
        "label": "1-120 chars",
        "timeframe": "Optional",
        "candles": "Optional",
        "pageSize": "Optional"
      },
      "effects": [
        "navigate",
        "quota",
        "network",
        "write"
      ]
    },
    {
      "type": "ui.waitIdle",
      "description": "Wait until visually settled: chart history/replay/feed discovery done, no busy spinners or finite animations, fonts loaded, 2 stable frames. Returns {idle,waitedMs,pending}; TIMEOUT lists pending.",
      "mutates": false,
      "params": {
        "timeoutMs": "Optional 100-60000, default 8000.",
        "scope": "Optional data-demo-id subtree."
      },
      "effects": [
        "none"
      ]
    },
    {
      "type": "ui.listTargets",
      "description": "List named demo targets {id,label,role,visible,rect{x,y,w,h} CSS px,viewport}; PII boxes have redact:true.",
      "mutates": false,
      "params": {
        "scope": "Optional data-demo-id subtree."
      },
      "effects": [
        "none"
      ]
    },
    {
      "type": "ui.getTargetRect",
      "description": "Rect of one demo target, first visible unless nth. TARGET_NOT_FOUND/TARGET_HIDDEN.",
      "mutates": false,
      "params": {
        "id": "Target id from ui.listTargets.",
        "nth": "Optional 0-based match index."
      },
      "effects": [
        "none"
      ]
    },
    {
      "type": "demo.prepare",
      "description": "Ephemeral presentation mode: hide tours/toasts/banners, optionally freeze clock labels, redact PII, hide cursor. Nothing persisted; no write grant. Returns previous; demo.reset restores.",
      "mutates": false,
      "params": {
        "hideTours": "bool, default true",
        "hideToasts": "bool, default true",
        "hideCookieBanner": "bool, default true",
        "freezeClock": "ISO time for clock labels",
        "redact": "bool",
        "cursor": "bool; false hides it"
      },
      "effects": [
        "ui"
      ]
    },
    {
      "type": "demo.reset",
      "description": "Leave presentation mode; clears redaction and frozen clock.",
      "mutates": false,
      "params": {},
      "effects": [
        "ui"
      ]
    },
    {
      "type": "demo.redact",
      "description": "Blur PII (account, contact, broker ids, balances) plus optional selectors. Ephemeral.",
      "mutates": false,
      "params": {
        "enable": "Required bool",
        "selectors": "Optional up to 20 extra CSS selectors."
      },
      "effects": [
        "ui"
      ]
    },
    {
      "type": "screening.getState",
      "description": "Read mounted Scanner draft, revisions and run status without opening it. Unmounted: ready:false, draft:null. Use screening.show to open. Requires real sign-in.",
      "mutates": false,
      "params": {},
      "effects": [
        "none"
      ]
    },
    {
      "type": "screening.show",
      "description": "Switch the visible Scanner or Scanned History view without running or changing rules. Leaving historical results clears that comparison.",
      "mutates": false,
      "params": {
        "view": "scanner|history; history requires advertised support."
      },
      "effects": [
        "panel"
      ]
    },
    {
      "type": "screening.catalog",
      "description": "Read server presets, fields, SQL schema, original strategy catalog and account limits. Strategy discovery failures are explicit; does not scan or open Scanner.",
      "mutates": false,
      "params": {},
      "effects": [
        "network"
      ]
    },
    {
      "type": "screening.listUniverses",
      "description": "List available active, saved watchlist, flagged and predefined category choices. Explicit symbols are also supported. Does not open Scanner.",
      "mutates": false,
      "params": {},
      "effects": [
        "none"
      ]
    },
    {
      "type": "screening.configure",
      "description": "Replace the visible rules and optionally select a universe, without executing. Read getState first.",
      "mutates": false,
      "params": {
        "definition": "Complete preset/custom/sql/classic definition without tickers; use catalog. Classic uses screeners:[{name,parameters}] from the advertised strategy catalog.",
        "universe": "Optional {kind:active|watchlist|flag|category|symbols,name?,tickers?}.",
        "expectedRevision": "Required visible draft revision from getState."
      },
      "effects": [
        "panel"
      ]
    },
    {
      "type": "screening.run",
      "description": "Start the visible preset/custom/SQL/Classic scan once. Consumes allowance, including cache hits. Poll getResults; no automatic retry.",
      "mutates": false,
      "params": {
        "expectedRevision": "Required current visible draft revision.",
        "cacheMode": "Optional refresh or prefer_cache (matching result under 60s); requires advertised support. Classic is refresh-only."
      },
      "effects": [
        "quota",
        "network",
        "panel"
      ]
    },
    {
      "type": "screening.getResults",
      "description": "Read this visible run's bounded results, warnings and pagination. Closing Scan cancels pending work; with Scanner closed returns RUN_NOT_FOUND without opening it.",
      "mutates": false,
      "params": {
        "runId": "Required ID from run.",
        "offset": "Optional zero-based row offset.",
        "limit": "Optional 1-25 rows, default 10."
      },
      "effects": [
        "none"
      ]
    },
    {
      "type": "screening.cancel",
      "description": "Cancel the current visible run; Scanner closed: RUN_NOT_FOUND, never opens. Submitted server work may count toward allowance.",
      "mutates": false,
      "params": {
        "runId": "Required ID from run."
      },
      "effects": [
        "write"
      ]
    },
    {
      "type": "screening.getAnalysis",
      "description": "Read the actual visible results grid, discovered column IDs, analysis revision and paged filtered rows across all pages. No query; never opens Scanner.",
      "mutates": false,
      "params": {
        "runId": "Current completed run/history ID.",
        "offset": "Optional filtered-row offset, 0-1000.",
        "limit": "Optional 1-25 rows, default 10.",
        "columnOffset": "Optional column offset, 0-10000.",
        "columnLimit": "Optional 1-50 columns, default 25."
      },
      "effects": [
        "none"
      ]
    },
    {
      "type": "screening.setAnalysis",
      "description": "Change the actual grid's display/filter/selection without scanning. Discover column IDs and revision through getAnalysis first. Scanner closed: RUN_NOT_FOUND.",
      "mutates": false,
      "params": {
        "runId": "Current completed run/history ID.",
        "expectedAnalysisRevision": "Current positive analysis revision.",
        "search": "Optional search text, at most 500 characters.",
        "filters": "Replace filters with up to 20 {columnId,operator,value?}; at most two AND conditions per column; operators eq|neq|gt|gte|lt|lte|contains|startsWith|endsWith|blank|notBlank; typed values.",
        "sort": "Replace sorting with up to 20 {columnId,direction:asc|desc}.",
        "hiddenColumns": "Replace hidden metric columns with up to 200 discovered IDs.",
        "selectedTickers": "Replace selection with up to 2500 unique canonical returned tickers; hidden selections do not refine.",
        "expanded": "Optional boolean: open/close expanded analysis.",
        "reset": "Optional true to reset the grid; cannot combine with other changes."
      },
      "effects": [
        "panel"
      ]
    },
    {
      "type": "screening.refine",
      "description": "Use the actual filtered or filtered-selected grid stocks as the next universe, retaining prior metric stages. Does not execute; configure next rules without universe, then run. Scanner closed: RUN_NOT_FOUND.",
      "mutates": false,
      "params": {
        "runId": "Current completed run/history ID.",
        "expectedRevision": "Current draft revision.",
        "expectedAnalysisRevision": "Current grid revision from getAnalysis.",
        "scope": "filtered|selected; includes all filtered pages, excludes hidden selections."
      },
      "effects": [
        "panel"
      ]
    },
    {
      "type": "screening.listSaved",
      "description": "Refresh this account's cloud-saved screener metadata. Does not load, run or open Scanner.",
      "mutates": false,
      "params": {
        "offset": "Optional zero-based offset.",
        "limit": "Optional 1-25 items, default 10."
      },
      "effects": [
        "network"
      ]
    },
    {
      "type": "screening.listHistory",
      "description": "List this account's retained completed scans, not saved screener rules. Uncharged, no execution; does not open Scanner.",
      "mutates": false,
      "params": {
        "offset": "Optional zero-based offset.",
        "limit": "Optional 1-25 metadata items, default 10."
      },
      "effects": [
        "network"
      ]
    },
    {
      "type": "screening.openHistory",
      "description": "Open a persisted result snapshot in the visible scanner. Does not rerun, consume allowance or change the current draft/universe. Use returned runId with getResults.",
      "mutates": false,
      "params": {
        "id": "Discovered scan history ID."
      },
      "effects": [
        "panel",
        "network"
      ]
    },
    {
      "type": "screening.useHistorySettings",
      "description": "Copy the currently opened historical scan's rules and original stocks into the visible draft. No execution; starts an independent comparison on next run. Scanner closed: RUN_NOT_FOUND.",
      "mutates": false,
      "params": {
        "runId": "Currently opened historical run ID.",
        "expectedRevision": "Current draft revision."
      },
      "effects": [
        "panel"
      ]
    },
    {
      "type": "screening.deleteHistory",
      "description": "Delete only this account's immutable scan snapshot, not saved rules. Requires real sign-in, cloud-write grant and retry key.",
      "mutates": true,
      "params": {
        "id": "Discovered scan history ID."
      },
      "effects": [
        "network",
        "panel",
        "write"
      ]
    },
    {
      "type": "screening.load",
      "description": "Load saved rules into the visible UI without running; retain the currently selected universe.",
      "mutates": false,
      "params": {
        "id": "Saved screener ID.",
        "expectedRevision": "Required current visible draft revision."
      },
      "effects": [
        "panel",
        "network"
      ]
    },
    {
      "type": "screening.save",
      "description": "Persist visible rules to this account's cloud storage. Requires real sign-in, cloud-write grant and retry key. Updates need id and etag; omitted id creates a copy.",
      "mutates": true,
      "params": {
        "name": "1-120 characters.",
        "description": "Optional description up to 1000 characters.",
        "id": "Optional saved ID.",
        "etag": "Required with id.",
        "expectedRevision": "Required current visible draft revision."
      },
      "effects": [
        "network",
        "panel",
        "write"
      ]
    },
    {
      "type": "screening.delete",
      "description": "Delete a cloud-saved screener at its current etag. Requires cloud-write grant and retry key; leaves the visible draft intact.",
      "mutates": true,
      "params": {
        "id": "Saved screener ID.",
        "etag": "Current saved etag."
      },
      "effects": [
        "network",
        "panel",
        "write"
      ]
    },
    {
      "type": "patterns.getState",
      "description": "Read mounted Historical Patterns draft/revisions and job state without opening it. Unmounted: ready:false, draft:null. Use patterns.show to open.",
      "mutates": false,
      "params": {},
      "effects": [
        "none"
      ]
    },
    {
      "type": "patterns.show",
      "description": "Open the existing Historical Patterns sidebar, optionally expanded. Keeps the current study and chart unchanged.",
      "mutates": false,
      "params": {
        "expanded": "Optional boolean."
      },
      "effects": [
        "panel"
      ]
    },
    {
      "type": "patterns.hide",
      "description": "Close Historical Patterns and cancel pending study work. Applied results remain in this account's mounted workspace.",
      "mutates": false,
      "params": {},
      "effects": [
        "panel",
        "write"
      ]
    },
    {
      "type": "patterns.searchSymbols",
      "description": "Search the active chart feed's NSE catalog (max 25). Read-only: does not open the sidebar, select a ticker, run analysis or switch feeds.",
      "mutates": false,
      "params": {
        "query": "1-100 characters."
      },
      "effects": [
        "none"
      ]
    },
    {
      "type": "patterns.configure",
      "description": "Replace the visible study draft without executing. NSE regular-session 15m only; no provider fallback.",
